def getLifelogs(started_at_gte=None, started_at_lte=None, ended_at_gte=None, ended_at_lte=None, status=None, source_provider=None, language=None, tag=None, participant=None, sort=None, limit=None, offset=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0427000" if __import__("os").path.isdir("./environment_mix/0427000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 date-time string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            raise ValueError(f"{field} must be an RFC3339 date-time string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    # Validate inputs
    allowed_status = {"available", "processing", "redacted", "deleted"}
    allowed_source = {"limitless"}
    allowed_sort = {"started_at", "-started_at", "created_at", "-created_at"}

    try:
        dt_started_gte = _parse_dt(started_at_gte, "started_at_gte")
        dt_started_lte = _parse_dt(started_at_lte, "started_at_lte")
        dt_ended_gte = _parse_dt(ended_at_gte, "ended_at_gte")
        dt_ended_lte = _parse_dt(ended_at_lte, "ended_at_lte")
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of: available, processing, redacted, deleted")
    if source_provider is not None and (not isinstance(source_provider, str) or source_provider not in allowed_source):
        return _err("VALIDATION_ERROR", "source_provider must be 'limitless'")
    if language is not None and not isinstance(language, str):
        return _err("VALIDATION_ERROR", "language must be a string")
    if tag is not None and not isinstance(tag, str):
        return _err("VALIDATION_ERROR", "tag must be a string")
    if participant is not None and not isinstance(participant, str):
        return _err("VALIDATION_ERROR", "participant must be a string")
    if sort is not None and (not isinstance(sort, str) or sort not in allowed_sort):
        return _err("VALIDATION_ERROR", "sort must be one of: started_at, -started_at, created_at, -created_at")

    if limit is None:
        limit = 50
    if offset is None:
        offset = 0
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    lifelog_entries = _load("lifelog_entries.json")
    search_requests = _load("search_requests.json")

    # Authenticate ambiently: find any active key for any active client that can perform lifelogs:read
    def _is_key_active_row(k):
        if k.get("status") != "active":
            return False
        exp = k.get("expires_at")
        if exp:
            try:
                exp_dt = _parse_dt(exp, "expires_at")
            except ValueError:
                return False
            if exp_dt <= now.replace(tzinfo=datetime.timezone.utc):
                return False
        return True

    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict) and c.get("id")}
    active_clients = {cid for cid, c in client_by_id.items() if c.get("status") == "active"}

    candidate_key = None
    candidate_client = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        cid = k.get("client_id")
        if cid not in active_clients:
            continue
        if not _is_key_active_row(k):
            continue
        scopes = k.get("scopes")
        if not isinstance(scopes, list):
            continue
        if "lifelogs:read" not in scopes:
            continue
        candidate_key = k
        candidate_client = client_by_id.get(cid)
        break

    latency_ms = int((time.time() - t0) * 1000)

    if not candidate_key or not candidate_client:
        # No viable auth context found
        return _err("UNAUTHORIZED", "No active API key with required scope found")

    client_id = candidate_client["id"]
    rate_limit = candidate_client.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int) or rate_limit < 1:
        rate_limit = 60

    # Rate limiting (rolling 60s) for this client across tool invocations.
    # We have only search_requests as the observable log collection; use it for all tools.
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        ts = r.get("created_at")
        if not isinstance(ts, str):
            continue
        try:
            rdt = _parse_dt(ts, "created_at")
        except ValueError:
            continue
        if rdt >= cutoff.replace(tzinfo=datetime.timezone.utc):
            recent += 1

    if recent >= rate_limit:
        # Excess requests must be rejected for other tools
        req_id = f"srch_{int(time.time()*1000)}_{os.getpid()}"
        search_requests.append({
            "id": req_id,
            "client_id": client_id,
            "api_key_id": candidate_key.get("id"),
            "status": "rate_limited",
            "query_text": None,
            "filters": {"tool": "getLifelogs"},
            "limit": limit,
            "offset": offset,
            "results_count": None,
            "latency_ms": latency_ms,
            "error_code": "RATE_LIMIT",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("search_requests.json", search_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Apply default status filtering: include available/redacted; exclude deleted by default.
    def_statuses = {"available", "redacted"}
    if status is None:
        allowed_statuses = def_statuses
    else:
        # Tool allows any status filter; still scoped by business rules? getLifelogs excludes deleted by default, not always.
        allowed_statuses = {status}

    def _dt_from_row(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        try:
            return _parse_dt(v, "row_dt")
        except ValueError:
            return None

    def _contains_ci(hay, needle):
        if hay is None or needle is None:
            return False
        return str(needle).lower() in str(hay).lower()

    # Filter entries
    filtered = []
    for e in lifelog_entries:
        if not isinstance(e, dict):
            continue
        if e.get("client_id") != client_id:
            continue
        st = e.get("status")
        if st not in allowed_statuses:
            continue
        # Exclude deleted if default filter; already handled by allowed_statuses.
        if source_provider is not None and e.get("source_provider") != source_provider:
            continue
        if language is not None and e.get("language") != language:
            continue
        if tag is not None:
            tags = e.get("tags")
            if not isinstance(tags, list) or tag not in tags:
                continue
        if participant is not None:
            parts = e.get("participants")
            if not isinstance(parts, list) or participant not in parts:
                continue

        sdt = _dt_from_row(e.get("started_at"))
        edt = _dt_from_row(e.get("ended_at"))

        if dt_started_gte is not None:
            if sdt is None or sdt < dt_started_gte:
                continue
        if dt_started_lte is not None:
            if sdt is None or sdt > dt_started_lte:
                continue
        if dt_ended_gte is not None:
            if edt is None or edt < dt_ended_gte:
                continue
        if dt_ended_lte is not None:
            if edt is None or edt > dt_ended_lte:
                continue

        filtered.append(e)

    # Sort
    sort_key = sort or "-started_at"

    def _sort_dt(e, field):
        v = e.get(field)
        dt = _dt_from_row(v)
        if dt is None:
            # stable: push nulls to end for desc, to start for asc by using extreme
            return None
        return dt

    reverse = sort_key.startswith("-")
    key_field = sort_key[1:] if reverse else sort_key

    if key_field not in ("started_at", "created_at"):
        key_field = "started_at"

    # Implement null-safe sorting
    def _cmp_key(e):
        dtv = _sort_dt(e, key_field)
        # For reverse (desc), None should be last; for asc, None should be first
        if dtv is None:
            return (1 if reverse else 0, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        return (0 if reverse else 1, dtv)

    filtered.sort(key=_cmp_key, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    has_more = offset + limit < total

    # Update last_used_at on successful authenticated call
    candidate_key["last_used_at"] = now_iso
    candidate_key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # Log request as completed
    req_id = f"srch_{int(time.time()*1000)}_{os.getpid()}"
    search_requests.append({
        "id": req_id,
        "client_id": client_id,
        "api_key_id": candidate_key.get("id"),
        "status": "completed",
        "query_text": None,
        "filters": {
            "tool": "getLifelogs",
            "started_at_gte": started_at_gte,
            "started_at_lte": started_at_lte,
            "ended_at_gte": ended_at_gte,
            "ended_at_lte": ended_at_lte,
            "status": status,
            "source_provider": source_provider,
            "language": language,
            "tag": tag,
            "participant": participant,
            "sort": sort_key
        },
        "limit": limit,
        "offset": offset,
        "results_count": len(page),
        "latency_ms": int((time.time() - t0) * 1000),
        "error_code": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("search_requests.json", search_requests)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "next_cursor": (offset + limit) if has_more else None
        }
    }

def getLifelogEntry(entry_id, include_assets=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0427000" if __import__("os").path.isdir("./environment_mix/0427000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    if not isinstance(entry_id, str) or not re.match(r"^lml_log_[0-9A-Z]+$", entry_id):
        return _err("VALIDATION_ERROR", "entry_id must match pattern ^lml_log_[0-9A-Z]+$")

    if include_assets is None:
        include_assets = False
    if not isinstance(include_assets, bool):
        return _err("VALIDATION_ERROR", "include_assets must be a boolean")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    lifelog_entries = _load("lifelog_entries.json")
    lifelog_assets = _load("lifelog_entry_assets.json")
    search_requests = _load("search_requests.json")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    # Authenticate ambiently: need lifelogs:read scope
    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict) and c.get("id")}
    active_clients = {cid for cid, c in client_by_id.items() if c.get("status") == "active"}

    def _key_active(k):
        if k.get("status") != "active":
            return False
        exp = k.get("expires_at")
        if exp:
            exp_dt = _parse_dt(exp)
            if exp_dt is None:
                return False
            if exp_dt <= now.replace(tzinfo=datetime.timezone.utc):
                return False
        return True

    candidate_key = None
    candidate_client = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        cid = k.get("client_id")
        if cid not in active_clients:
            continue
        scopes = k.get("scopes")
        if not isinstance(scopes, list) or "lifelogs:read" not in scopes:
            continue
        if not _key_active(k):
            continue
        candidate_key = k
        candidate_client = client_by_id.get(cid)
        break

    if not candidate_key or not candidate_client:
        return _err("UNAUTHORIZED", "No active API key with required scope found")

    client_id = candidate_client["id"]
    rate_limit = candidate_client.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int) or rate_limit < 1:
        rate_limit = 60

    # Rate limiting using search_requests as request log
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        rdt = _parse_dt(r.get("created_at"))
        if rdt is None:
            continue
        if rdt >= cutoff.replace(tzinfo=datetime.timezone.utc):
            recent += 1

    if recent >= rate_limit:
        req_id = f"srch_{int(time.time()*1000)}_{os.getpid()}"
        search_requests.append({
            "id": req_id,
            "client_id": client_id,
            "api_key_id": candidate_key.get("id"),
            "status": "rate_limited",
            "query_text": None,
            "filters": {"tool": "getLifelogEntry", "entry_id": entry_id},
            "limit": 1,
            "offset": 0,
            "results_count": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "RATE_LIMIT",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("search_requests.json", search_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Find entry scoped to client
    entry = None
    for e in lifelog_entries:
        if isinstance(e, dict) and e.get("id") == entry_id and e.get("client_id") == client_id:
            entry = e
            break

    if entry is None:
        # Log completed call with zero results (reads return empty set normally, but this endpoint is singular; use NOT_FOUND)
        req_id = f"srch_{int(time.time()*1000)}_{os.getpid()}"
        search_requests.append({
            "id": req_id,
            "client_id": client_id,
            "api_key_id": candidate_key.get("id"),
            "status": "completed",
            "query_text": None,
            "filters": {"tool": "getLifelogEntry", "entry_id": entry_id, "found": False},
            "limit": 1,
            "offset": 0,
            "results_count": 0,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("search_requests.json", search_requests)
        return _err("NOT_FOUND", "Lifelog entry not found")

    # If deleted, still return row? Business rule: if found and not deleted, may include assets.
    # We'll return the entry even if deleted, but never include assets for deleted.
    response = {"data": entry}

    if include_assets and entry.get("status") != "deleted":
        assets = []
        for a in lifelog_assets:
            if not isinstance(a, dict):
                continue
            if a.get("entry_id") != entry_id:
                continue
            if a.get("status") == "deleted":
                continue
            assets.append(a)
        response["assets"] = assets

    # Update last_used_at on successful call
    candidate_key["last_used_at"] = now_iso
    candidate_key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # Log request
    req_id = f"srch_{int(time.time()*1000)}_{os.getpid()}"
    search_requests.append({
        "id": req_id,
        "client_id": client_id,
        "api_key_id": candidate_key.get("id"),
        "status": "completed",
        "query_text": None,
        "filters": {"tool": "getLifelogEntry", "entry_id": entry_id, "include_assets": include_assets},
        "limit": 1,
        "offset": 0,
        "results_count": 1,
        "latency_ms": int((time.time() - t0) * 1000),
        "error_code": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("search_requests.json", search_requests)

    return response

