            "client_id": client_id,
            "api_key_id": candidate_key.get("id"),
            "status": "rate_limited",
            "query_text": query,
            "filters": {
                "started_at_gte": started_at_gte,
                "started_at_lte": started_at_lte,
                "ended_at_gte": ended_at_gte,
                "ended_at_lte": ended_at_lte,
                "status": status,
                "source_provider": source_provider,
                "language": language,
                "tag": tag,
                "participant": participant
            },
            "limit": limit,
            "offset": offset,
            "results_count": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "RATE_LIMIT",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("search_requests.json", search_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    q = query.strip().lower()
    q_terms = [t for t in re.split(r"\s+", q) if t]

    def _dt_from_row(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        try:
            return _parse_dt(v, "row_dt")
        except ValueError:
            return None

    # Filter & score
    candidates = []
    for e in lifelog_entries:
        if not isinstance(e, dict):
            continue
        if e.get("client_id") != client_id:
            continue
        if e.get("status") == "deleted":
            continue
        if status is not None and e.get("status") != status:
            continue
        if source_provider is not None and e.get("source_provider") != source_provider:
            continue
        if language is not None and e.get("language") != language:
            continue
        if tag is not None:
            tags = e.get("tags")
            if not isinstance(tags, list) or tag not in tags:
                continue
        if participant is not None:
            parts = e.get("participants")
            if not isinstance(parts, list) or participant not in parts:
                continue

        sdt = _dt_from_row(e.get("started_at"))
        edt = _dt_from_row(e.get("ended_at"))
        if dt_started_gte is not None:
            if sdt is None or sdt < dt_started_gte:
                continue
        if dt_started_lte is not None:
            if sdt is None or sdt > dt_started_lte:
                continue
        if dt_ended_gte is not None:
            if edt is None or edt < dt_ended_gte:
                continue
        if dt_ended_lte is not None:
            if edt is None or edt > dt_ended_lte:
                continue

        hay = e.get("search_tsv") or ""
        if not isinstance(hay, str):
            hay = ""
        # fall back to summary + content_text
        s = e.get("summary")
        c = e.get("content_text")
        if isinstance(s, str):
            hay += " " + s
        if isinstance(c, str):
            hay += " " + c
        hay_l = hay.lower()

        # Simple term scoring: count term occurrences (presence-based)
        score = 0
        for term in q_terms:
            if term and term in hay_l:
                score += 1

        if score <= 0:
            continue

        candidates.append((score, e))

    # Sort by score desc, then started_at desc, then created_at desc
    def _parse_iso(v):
        dt = _dt_from_row(v)
        return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    candidates.sort(key=lambda se: (se[0], _parse_iso(se[1].get("started_at")), _parse_iso(se[1].get("created_at"))), reverse=True)
    rows = [e for _, e in candidates]

    total = len(rows)
    page = rows[offset: offset + limit]
    has_more = offset + limit < total

    # Update last_used_at on successful call
    candidate_key["last_used_at"] = now_iso
    candidate_key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # Log search request (completed)
    req_id = f"srch_{int(time.time()*1000)}_{os.getpid()}"
    latency_ms = int((time.time() - t0) * 1000)
    search_requests.append({
        "id": req_id,
        "client_id": client_id,
        "api_key_id": candidate_key.get("id"),
        "status": "completed",
        "query_text": query,
        "filters": {
            "started_at_gte": started_at_gte,
            "started_at_lte": started_at_lte,
            "ended_at_gte": ended_at_gte,
            "ended_at_lte": ended_at_lte,
            "status": status,
            "source_provider": source_provider,
            "language": language,
            "tag": tag,
            "participant": participant
        },
        "limit": limit,
        "offset": offset,
        "results_count": len(page),
        "latency_ms": latency_ms,
        "error_code": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("search_requests.json", search_requests)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "next_cursor": (offset + limit) if has_more else None
        }
    }

def createApiKey(scopes, name=None, expires_at=None, **_extra):
    import json, os, datetime, time, secrets, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0427000" if __import__("os").path.isdir("./environment_mix/0427000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Validate inputs
    if name is not None and not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string")
    if not isinstance(scopes, list) or len(scopes) < 1:
        return _err("VALIDATION_ERROR", "scopes must be a non-empty array")
    allowed = {"lifelogs:read", "lifelogs:search", "lifelogs:write", "keys:read", "keys:write"}
    for s in scopes:
        if not isinstance(s, str) or s not in allowed:
            return _err("VALIDATION_ERROR", "scopes contains an invalid value")
    # Store only supported scopes in schema (enum restricts api_keys.scopes to read/search)
    supported = {"lifelogs:read", "lifelogs:search"}
    stored_scopes = [s for s in scopes if s in supported]
    if not stored_scopes:
        return _err("VALIDATION_ERROR", "At least one of lifelogs:read or lifelogs:search is required for this service")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 date-time string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            raise ValueError(f"{field} must be an RFC3339 date-time string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    try:
        exp_dt = _parse_dt(expires_at, "expires_at") if expires_at is not None else None
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    # Ambient auth: choose an active client and an active key with keys:write OR any active key (since schema doesn't include that scope).
    # Per tool description: authenticated API client. We'll require there exists an active client at all, and pick it.
    active_clients = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)]
    if not active_clients:
        return _err("UNAUTHORIZED", "No active client available to authenticate the request")
    # pick one that has any active key (to reflect "authenticated"); if none, still allow? Tool says must authenticate; so require any active key.
    def _key_active(k):
        if k.get("status") != "active":
            return False
        exp = k.get("expires_at")
        if exp:
            try:
                kexp = _parse_dt(exp, "expires_at")
            except ValueError:
                return False
            if kexp <= now.replace(tzinfo=datetime.timezone.utc):
                return False
        return True

    client = None
    auth_key = None
    for c in active_clients:
        cid = c["id"]
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("client_id") != cid:
                continue
            if not _key_active(k):
                continue
            auth_key = k
            client = c
            break
        if client:
            break

    if client is None:
        return _err("UNAUTHORIZED", "No active API key available to authenticate the request")

    client_id = client["id"]

    # Rate limiting using search_requests log for all tools
    rate_limit = client.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int) or rate_limit < 1:
        rate_limit = 60
    cutoff = now - datetime.timedelta(seconds=60)

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    recent = 0
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        rdt = _parse_iso(r.get("created_at"))
        if rdt is None:
            continue
        if rdt >= cutoff.replace(tzinfo=datetime.timezone.utc):
            recent += 1
    if recent >= rate_limit:
        req_id = f"srch_{int(time.time()*1000)}_{os.getpid()}"
        search_requests.append({
            "id": req_id,
            "client_id": client_id,
            "api_key_id": auth_key.get("id") if auth_key else None,
            "status": "rate_limited",
            "query_text": None,
            "filters": {"tool": "createApiKey"},
            "limit": 1,
            "offset": 0,
            "results_count": None,
            "latency_ms": 0,
            "error_code": "RATE_LIMIT",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("search_requests.json", search_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Only active clients may create keys
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active")

    # Validate expires_at constraint: expires_at is null or expires_at > created_at
    if exp_dt is not None:
        if exp_dt <= now.replace(tzinfo=datetime.timezone.utc):
            return _err("VALIDATION_ERROR", "expires_at must be in the future")
    # Generate API key plaintext once; store hash+prefix
    plaintext = "lml_" + secrets.token_urlsafe(32)
    prefix = plaintext[:8]

    # Ensure unique (key_prefix, client_id) and unique key_hash
    # Use sha256 without salt here; store is only for identification; no auth by plaintext is possible in this system anyway.
    key_hash = hashlib.sha256(plaintext.encode("utf-8")).hexdigest()

    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("key_hash") == key_hash:
            # extremely unlikely; regenerate once
            plaintext = "lml_" + secrets.token_urlsafe(32)
            prefix = plaintext[:8]
            key_hash = hashlib.sha256(plaintext.encode("utf-8")).hexdigest()
            break

    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("client_id") == client_id and k.get("key_prefix") == prefix:
            # regenerate with different prefix
            plaintext = "lml_" + secrets.token_urlsafe(32)
            prefix = plaintext[:8]
            key_hash = hashlib.sha256(plaintext.encode("utf-8")).hexdigest()
            break

    # Create id
    new_id = f"key_{int(time.time()*1000)}_{secrets.token_hex(4)}"

    row = {
        "id": new_id,
        "client_id": client_id,
        "key_hash": key_hash,
        "key_prefix": prefix,
        "status": "active",
        "scopes": stored_scopes,
        "last_used_at": None,
        "expires_at": (exp_dt.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z") if exp_dt is not None else None),
        "created_at": now_iso,
        "updated_at": now_iso
    }

    api_keys.append(row)
    _save("api_keys.json", api_keys)

    # Mark auth key used (successful authenticated call)
    if auth_key is not None:
        auth_key["last_used_at"] = now_iso
        auth_key["updated_at"] = now_iso
        _save("api_keys.json", api_keys)

    # Log request
    req_id = f"srch_{int(time.time()*1000)}_{os.getpid()}"
    search_requests.append({
        "id": req_id,
        "client_id": client_id,
        "api_key_id": auth_key.get("id") if auth_key else None,
        "status": "completed",
        "query_text": None,
        "filters": {"tool": "createApiKey", "requested_scopes": scopes, "stored_scopes": stored_scopes},
        "limit": 1,
        "offset": 0,
        "results_count": 1,
        "latency_ms": 0,
        "error_code": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("search_requests.json", search_requests)

    return {
        "data": {
            "id": row["id"],
            "client_id": row["client_id"],
            "key_prefix": row["key_prefix"],
            "status": row["status"],
            "scopes": row["scopes"],
            "expires_at": row["expires_at"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
            "api_key": plaintext
        }
    }

def getApiKeys(status=None, key_prefix=None, limit=None, offset=None, sort=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0427000" if __import__("os").path.isdir("./environment_mix/0427000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # ---- validate inputs ----
    if status is not None and status not in ("active", "revoked", "expired"):
        return _err("VALIDATION_ERROR", "Invalid status. Must be one of: active, revoked, expired.", field="status")
    if key_prefix is not None and not isinstance(key_prefix, str):
        return _err("VALIDATION_ERROR", "key_prefix must be a string.", field="key_prefix")
    if limit is None:
        limit = 50
    if offset is None:
        offset = 0
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "offset must be a non-negative integer.", field="offset")
    if sort is None:
        sort = "-created_at"
    if sort not in ("created_at", "-created_at", "last_used_at", "-last_used_at"):
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    # ---- load store ----
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    def _rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    clients_r = _rows(clients)
    keys_r = _rows(keys)
    srq_r = _rows(search_requests)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    # ---- ambient auth resolution ----
    # No credential parameter exists for this tool; resolve a combination that can serve the request.
    client_by_id = {c.get("id"): c for c in clients_r if isinstance(c, dict) and c.get("id")}
    authed_key = None
    authed_client = None
    for k in keys_r:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        cid = k.get("client_id")
        c = client_by_id.get(cid)
        if not c or c.get("status") != "active":
            continue
        if "keys:read" not in (k.get("scopes") or []):
            continue
        # ignore expired-by-date active keys
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        authed_key = k
        authed_client = c
        break

    if authed_key is None or authed_client is None:
        # still record a failed attempt for observability (best-effort)
        try:
            srq_r.append({
                "id": "lml_srq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "client_id": None,
                "api_key_id": None,
                "status": "failed",
                "query_text": None,
                "filters": {"endpoint": "getApiKeys"},
                "limit": int(limit),
                "offset": int(offset),
                "results_count": None,
                "latency_ms": int((time.time() - t0) * 1000),
                "error_code": "AUTH_CONTEXT_MISSING",
                "created_at": now_iso,
                "updated_at": now_iso
            })
            if isinstance(search_requests, dict) and "rows" in search_requests:
                search_requests["rows"] = srq_r
                _save("search_requests.json", search_requests)
            else:
                _save("search_requests.json", srq_r)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Missing or invalid authentication context for keys:read on an active client.")

    # ---- rate limit (rolling 60s window over ALL tool invocations recorded in search_requests) ----
    rl = authed_client.get("rate_limit_per_minute")
    if not isinstance(rl, int) or rl < 1:
        rl = 60
    window_start = now - datetime.timedelta(seconds=60)
    invocations = 0
    for r in srq_r:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != authed_client.get("id"):
            continue
        ts = _parse_dt(r.get("created_at"))
        if ts is None:
            continue
        if ts >= window_start:
            invocations += 1
    if invocations >= rl:
        # For non-search tools: reject; also record rate limit event in search_requests for observability.
        try:
            srq_r.append({
                "id": "lml_srq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "client_id": authed_client.get("id"),
                "api_key_id": authed_key.get("id"),
                "status": "rate_limited",
                "query_text": None,
                "filters": {"endpoint": "getApiKeys"},
                "limit": int(limit),
                "offset": int(offset),
                "results_count": None,
                "latency_ms": int((time.time() - t0) * 1000),
                "error_code": "RATE_LIMIT_EXCEEDED",
                "created_at": now_iso,
                "updated_at": now_iso
            })
            if isinstance(search_requests, dict) and "rows" in search_requests:
                search_requests["rows"] = srq_r
                _save("search_requests.json", search_requests)
            else:
                _save("search_requests.json", srq_r)
        except Exception:
            pass
        return _err("RATE_LIMIT", "Rate limit exceeded for this client (rolling 60s window).")

    # ---- filter + sort + paginate ----
    client_id = authed_client.get("id")
    out = []
    for k in keys_r:
        if not isinstance(k, dict):
            continue
        if k.get("client_id") != client_id:
            continue
        if status is not None and k.get("status") != status:
            continue
        if key_prefix is not None and k.get("key_prefix") != key_prefix:
            continue
        # never return raw secret; datastore has only hash/prefix anyway
        out.append(dict(k))

    def _sort_key(row):
        if sort.endswith("created_at"):
            v = _parse_dt(row.get("created_at"))
        else:
            v = _parse_dt(row.get("last_used_at"))
        return v or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    reverse = sort.startswith("-")
    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)
    page = out[offset: offset + limit]
    has_more = (offset + limit) < total

    # ---- update last_used_at for successful auth'd call ----
    authed_key["last_used_at"] = now_iso
    authed_key["updated_at"] = authed_key.get("updated_at") or now_iso
    # persist key change
    for i, k in enumerate(keys_r):
        if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
            keys_r[i] = authed_key
            break
    if isinstance(keys, dict) and "rows" in keys:
        keys["rows"] = keys_r
        _save("api_keys.json", keys)
    else:
        _save("api_keys.json", keys_r)

    # ---- record invocation ----
    latency_ms = int((time.time() - t0) * 1000)
    srq_r.append({
        "id": "lml_srq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
        "client_id": client_id,
        "api_key_id": authed_key.get("id"),
        "status": "completed",
        "query_text": None,
        "filters": {"endpoint": "getApiKeys", "status": status, "key_prefix": key_prefix, "sort": sort},
        "limit": int(limit),
        "offset": int(offset),
        "results_count": len(page),
        "latency_ms": latency_ms,
        "error_code": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    if isinstance(search_requests, dict) and "rows" in search_requests:
        search_requests["rows"] = srq_r
        _save("search_requests.json", search_requests)
    else:
        _save("search_requests.json", srq_r)

    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "offset": offset, "has_more": has_more}
    }

def updateApiKey(api_key_id, status=None, scopes=None, expires_at=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0427000" if __import__("os").path.isdir("./environment_mix/0427000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    if not isinstance(api_key_id, str) or not re.match(r"^lml_key_[0-9A-Z]+$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must match ^lml_key_[0-9A-Z]+$.", field="api_key_id")
    if status is not None and status not in ("active", "revoked", "expired"):
        return _err("VALIDATION_ERROR", "Invalid status. Must be one of: active, revoked, expired.", field="status")

