    # Enforce constraint: if available then summary or content_text non-null
    if updated.get("status") == "available" and (updated.get("summary") is None and updated.get("content_text") is None):
        return _err("VALIDATION_ERROR", "When status='available', at least one of summary or content_text must be non-null.", field="status")

    # If deleted: soft-delete assets (transition to deleted) but keep rows
    if cur_status != "deleted" and status == "deleted":
        changed_any_asset = False
        for i, a in enumerate(assets_r):
            if not isinstance(a, dict):
                continue
            if a.get("entry_id") != existing.get("id"):
                continue
            if a.get("status") != "deleted":
                a2 = dict(a)
                a2["status"] = "deleted"
                a2["uri"] = None
                a2["updated_at"] = now_iso
                assets_r[i] = a2
                changed_any_asset = True
        if changed_any_asset:
            if isinstance(assets, dict) and "rows" in assets:
                assets["rows"] = assets_r
                _save("lifelog_entry_assets.json", assets)
            else:
                _save("lifelog_entry_assets.json", assets_r)

    updated["search_tsv"] = _materialize_search(updated.get("summary"), updated.get("content_text"))
    updated["updated_at"] = now_iso

    entries_r[existing_idx] = updated
    if isinstance(entries, dict) and "rows" in entries:
        entries["rows"] = entries_r
        _save("lifelog_entries.json", entries)
    else:
        _save("lifelog_entries.json", entries_r)

    # update last_used_at for authed_key
    authed_key["last_used_at"] = now_iso
    authed_key["updated_at"] = authed_key.get("updated_at") or now_iso
    for i, k in enumerate(keys_r):
        if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
            keys_r[i] = authed_key
            break
    if isinstance(keys, dict) and "rows" in keys:
        keys["rows"] = keys_r
        _save("api_keys.json", keys)
    else:
        _save("api_keys.json", keys_r)

    # record invocation
    srq_r.append({
        "id": "lml_srq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
        "client_id": client_id,
        "api_key_id": authed_key.get("id"),
        "status": "completed",
        "query_text": None,
        "filters": {"endpoint": "upsertLifelogEntry", "source_provider": source_provider, "provider_entry_id": provider_entry_id, "created": False},
        "limit": 1,
        "offset": 0,
        "results_count": 1,
        "latency_ms": int((time.time() - t0) * 1000),
        "error_code": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    if isinstance(search_requests, dict) and "rows" in search_requests:
        search_requests["rows"] = srq_r
        _save("search_requests.json", search_requests)
    else:
        _save("search_requests.json", srq_r)

    return {"data": dict(updated)}

def getSearchRequests(status=None, created_at_gte=None, created_at_lte=None, limit=None, offset=None, sort=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0427000" if __import__("os").path.isdir("./environment_mix/0427000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    if status is not None and status not in ("completed", "failed", "rate_limited"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if limit is None:
        limit = 50
    if offset is None:
        offset = 0
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "offset must be a non-negative integer.", field="offset")
    if sort is None:
        sort = "-created_at"
    if sort not in ("created_at", "-created_at"):
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be a date-time string.", field=field)
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be RFC3339 date-time.", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    gte = _parse_dt(created_at_gte, "created_at_gte") if created_at_gte is not None else None
    if isinstance(gte, dict) and "error" in gte:
        return gte
    lte = _parse_dt(created_at_lte, "created_at_lte") if created_at_lte is not None else None
    if isinstance(lte, dict) and "error" in lte:
        return lte
    if gte is not None and lte is not None and lte < gte:
        return _err("VALIDATION_ERROR", "created_at_lte must be >= created_at_gte.", field="created_at_lte")

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    def _rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    clients_r = _rows(clients)
    keys_r = _rows(keys)
    srq_r = _rows(search_requests)

    client_by_id = {c.get("id"): c for c in clients_r if isinstance(c, dict) and c.get("id")}

    def _dt_or_none(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    # Auth: active key with keys:read on active client (analytics/debug)
    authed_key = None
    authed_client = None
    for k in keys_r:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if "keys:read" not in (k.get("scopes") or []):
            continue
        c = client_by_id.get(k.get("client_id"))
        if not c or c.get("status") != "active":
            continue
        exp = _dt_or_none(k.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        authed_key = k
        authed_client = c
        break

    if authed_key is None or authed_client is None:
        # record failed attempt (best-effort)
        try:
            srq_r.append({
                "id": "lml_srq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "client_id": None,
                "api_key_id": None,
                "status": "failed",
                "query_text": None,
                "filters": {"endpoint": "getSearchRequests"},
                "limit": int(limit),
                "offset": int(offset),
                "results_count": None,
                "latency_ms": int((time.time() - t0) * 1000),
                "error_code": "AUTH_CONTEXT_MISSING",
                "created_at": now_iso,
                "updated_at": now_iso
            })
            if isinstance(search_requests, dict) and "rows" in search_requests:
                search_requests["rows"] = srq_r
                _save("search_requests.json", search_requests)
            else:
                _save("search_requests.json", srq_r)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Missing or invalid authentication context for keys:read on an active client.")

    # Rate limit
    rl = authed_client.get("rate_limit_per_minute")
    if not isinstance(rl, int) or rl < 1:
        rl = 60
    window_start = now - datetime.timedelta(seconds=60)
    invocations = 0
    for r in srq_r:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != authed_client.get("id"):
            continue
        ts = _dt_or_none(r.get("created_at"))
        if ts is None:
            continue
        if ts >= window_start:
            invocations += 1
    if invocations >= rl:
        try:
            srq_r.append({
                "id": "lml_srq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "client_id": authed_client.get("id"),
                "api_key_id": authed_key.get("id"),
                "status": "rate_limited",
                "query_text": None,
                "filters": {"endpoint": "getSearchRequests"},
                "limit": int(limit),
                "offset": int(offset),
                "results_count": None,
                "latency_ms": int((time.time() - t0) * 1000),
                "error_code": "RATE_LIMIT_EXCEEDED",
                "created_at": now_iso,
                "updated_at": now_iso
            })
            if isinstance(search_requests, dict) and "rows" in search_requests:
                search_requests["rows"] = srq_r
                _save("search_requests.json", search_requests)
            else:
                _save("search_requests.json", srq_r)
        except Exception:
            pass
        return _err("RATE_LIMIT", "Rate limit exceeded for this client (rolling 60s window).")

    client_id = authed_client.get("id")

    # Filter
    out = []
    for r in srq_r:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        ts = _dt_or_none(r.get("created_at"))
        if gte is not None and (ts is None or ts < gte):
            continue
        if lte is not None and (ts is None or ts > lte):
            continue
        out.append(dict(r))

    reverse = sort.startswith("-")
    out.sort(key=lambda x: _dt_or_none(x.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=reverse)

    total = len(out)
    page = out[offset: offset + limit]
    has_more = (offset + limit) < total

    # Update last_used_at for authed_key
    authed_key["last_used_at"] = now_iso
    authed_key["updated_at"] = authed_key.get("updated_at") or now_iso
    # persist key
    for i, k in enumerate(keys_r):
        if isinstance(k, dict) and k.get("id") == authed_key.get("id"):
            keys_r[i] = authed_key
            break
    keys_store = keys
    if isinstance(keys_store, dict) and "rows" in keys_store:
        keys_store["rows"] = keys_r
        _save("api_keys.json", keys_store)
    else:
        _save("api_keys.json", keys_r)

    # Record invocation (completed)
    srq_r.append({
        "id": "lml_srq_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
        "client_id": client_id,
        "api_key_id": authed_key.get("id"),
        "status": "completed",
        "query_text": None,
        "filters": {"endpoint": "getSearchRequests", "status": status, "created_at_gte": created_at_gte, "created_at_lte": created_at_lte, "sort": sort},
        "limit": int(limit),
        "offset": int(offset),
        "results_count": len(page),
        "latency_ms": int((time.time() - t0) * 1000),
        "error_code": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    if isinstance(search_requests, dict) and "rows" in search_requests:
        search_requests["rows"] = srq_r
        _save("search_requests.json", search_requests)
    else:
        _save("search_requests.json", srq_r)

    return {"data": page, "meta": {"total": total, "limit": limit, "offset": offset, "has_more": has_more}}
